WITH lines AS (SELECT id, service, host, level, latency_ms, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, v) SELECT CASE WHEN latency_ms >= 2131 THEN 'LARGE' ELSE 'SMALL' END AS latency_ms_tier, attr_key, BIT_AND(latency_ms) AS latency_ms_bit_and, COUNT(CASE WHEN level = 'INFO' THEN 1 END) AS info_count, SUM(latency_ms) AS total_latency_ms, SIZE(COLLECT_SET(host)) AS num_hosts, MIN(latency_ms) AS min_latency_ms, SORT_ARRAY(COLLECT_SET(level)) AS level_list, GROUPING_ID() AS gid FROM lines GROUP BY GROUPING SETS ((CASE WHEN latency_ms >= 2131 THEN 'LARGE' ELSE 'SMALL' END, attr_key), (CASE WHEN latency_ms >= 2131 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY min_latency_ms DESC;
